<!DOCTYPE html>
<html>
<head>
  <title>Random Joke</title>
</head>
<body>
  <button id="button">Click me!</button>
  <script>
    // Define an array of jokes
    const jokes = ["Why was the math book sad?", "Why did the scarecrow win an award?", "Why don't lobsters share?", "Why did the chicken cross the playground?"];
    // Define a function to generate a random joke
    function getRandomJoke() {
      // Get a random number between 0 and 3 (inclusive)
      const randomNumber = Math.floor(Math.random() * jokes.length);
      // Return the joke at the specified index
      return jokes[randomNumber];
    }
    // Add an event listener to the button
    document.getElementById("button").addEventListener("click", getRandomJoke);
  </script>
</body>
</html>
```
