function findHighestCommonAncestor(tree1, tree2) {
  // Create a stack to store the nodes to be processed
  const stack = [tree1, tree2];

  // Loop until the stack is empty
  while (stack.length > 0) {
    // Pop the top node from the stack
    const node1 = stack.pop();

    // Loop through the children of the current node
    for (let i = 0; i < node1.children.length; i++) {
      // If the child node exists in the other tree, add it to the stack
      if (tree2.includes(node1.children[i])) {
        stack.push(tree2.find(node1.children[i]));
      }
    }
  }

  // The current HCA is the current node
  return node1;
}
```
